import React from 'react';

const Contact = () => {
  return (
    <div style={{ padding: '20px', marginTop: '20px' }}>
      <h1>Contact Page</h1>
       <p>Developers:
        <br /><b>Zeill Andrew C. Vista<br />
        Abby Julian Adriano<br />
        Leegray Benarez
        </b>
      </p>
      <p>Version: 1.0.0</p>
      <p>License: MIT</p>
      <p>For more information, visit our <a href="/">GitHub repository</a>.</p>
      <p>Contact us at: <a href="mailto:andrewvista2005@gmail.com">EMAIL</a>
      </p>
    </div>
  );
};

export default Contact;
